@import url("https://fonts.googleapis.com/css2?family=JetBrains+Mono:wght@300;400;500;600;700&display=swap");

@tailwind utilities;

/* Override Radix Themes font with JetBrains Mono */
.radix-themes {
  --default-font-family: "JetBrains Mono", "Fira Code", ui-monospace, monospace;
  --code-font-family: "JetBrains Mono", "Fira Code", ui-monospace, monospace;
  --heading-font-family: "JetBrains Mono", "Fira Code", ui-monospace, monospace;
}

/* Tighten scrollbars */
::-webkit-scrollbar {
  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: transparent;
}
::-webkit-scrollbar-thumb {
  background: var(--gray-5);
  border-radius: 9999px;
}
::-webkit-scrollbar-thumb:hover {
  background: var(--gray-7);
}

/* ── react-day-picker v8 — themed to Radix Themes orange/sand ── */
.rdp {
  --rdp-cell-size: 34px;
  --rdp-accent-color: var(--orange-9);
  --rdp-background-color: var(--orange-3);
  --rdp-outline: 2px solid var(--orange-9);
  --rdp-outline-selected: 2px solid var(--orange-9);
  margin: 0;
  font-family: inherit;
  font-size: var(--font-size-2);
}

.rdp-caption {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 8px;
}

.rdp-caption_label {
  font-size: var(--font-size-2);
  font-weight: 600;
  color: var(--gray-12);
}

.rdp-nav {
  display: flex;
  gap: 4px;
}

.rdp-nav_button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: var(--radius-2);
  border: 1px solid var(--gray-4);
  background: transparent;
  color: var(--gray-11);
  cursor: pointer;
  transition: background 0.12s;
}

.rdp-nav_button:hover {
  background: var(--gray-3);
}

.rdp-head_cell {
  font-size: 10px;
  font-weight: 600;
  color: var(--gray-9);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  padding-bottom: 4px;
  width: var(--rdp-cell-size);
  text-align: center;
}

.rdp-tbody {
  border-collapse: collapse;
}

.rdp-cell {
  padding: 1px;
  text-align: center;
}

.rdp-day {
  width: var(--rdp-cell-size);
  height: var(--rdp-cell-size);
  border-radius: var(--radius-2);
  font-size: var(--font-size-2);
  color: var(--gray-12);
  border: none;
  background: transparent;
  cursor: pointer;
  transition: background 0.1s, color 0.1s;
  font-family: inherit;
}

.rdp-day:hover:not([disabled]):not(.rdp-day_selected) {
  background: var(--gray-3);
}

.rdp-day_selected,
.rdp-day_selected:hover {
  background: var(--orange-9) !important;
  color: white !important;
  font-weight: 600;
}

.rdp-day_today:not(.rdp-day_selected) {
  font-weight: 700;
  color: var(--orange-11);
}

.rdp-day_outside {
  color: var(--gray-7);
}

.rdp-day[disabled] {
  opacity: 0.4;
  cursor: default;
}

/* Drag-over state for CSV drop zone */
.drop-zone {
  border: 2px dashed var(--gray-5);
  border-radius: var(--radius-3);
  transition: border-color 0.15s, background-color 0.15s;
  cursor: pointer;
}
.drop-zone:hover,
.drop-zone--active {
  border-color: var(--accent-8);
  background-color: var(--accent-2);
}

